from curva import CurvaError, NotFoundError, InvalidRequestError

try:
    client.feedback(decision_id, "team", label)
except NotFoundError:
    pass                          # rule answer, skipped question, or wrong id: nothing to learn
except InvalidRequestError as e:
    log.error("bad label for team: %s", e.message)   # fix the mapping in your code
except CurvaError as e:
    retry_later(decision_id, "team", label, e.status)

q = {"team": Choice("Which team?", {"billing": "", "technical": "", "sales": ""}, min_confidence=0.9)}
d = client.decide(ticket, q, project="support")

if d["team"].abstain:
    team = ask_a_human(ticket)                  # a person decides...
    client.feedback(d.id, "team", team)         # ...and Curva learns from it
else:
    route(ticket, d["team"].choice)
